{
  "items": [
    {
      "title": "Comparative Political Data Set 1960–2023 (CPDS)",
      "url_or_doi": "https://cpds-data.org/",
      "justification": "The Comparative Political Data Set (CPDS) provides annual political, institutional, government composition, and macro-level data for 36 democratic OECD and EU member countries (including Belgium, Bulgaria, Czech Republic, Denmark, Germany, Estonia, Ireland, Greece, Spain, France, Italy, Cyprus, Latvia, Lithuania, Luxembourg, Hungary, Malta, Netherlands, Austria, Poland, Portugal, Romania, Slovenia, Slovakia, Finland, Sweden, Croatia, Turkey, and the UK) updated through 2023."
    },
    {
      "title": "Varieties of Democracy (V-Dem) Dataset",
      "url_or_doi": "https://www.v-dem.net/data/the-v-dem-dataset/",
      "justification": "The V-Dem dataset provides multi-dimensional indicators of democratic governance, political institutions, state capacity, and international political engagement covering all requested European, Balkan, EU-candidate, and Eastern Partnership countries throughout the 2020s."
    },
    {
      "title": "Manifesto Project Main Dataset",
      "url_or_doi": "https://doi.org/10.25522/manifesto.mpds.2026a",
      "justification": "The Manifesto Project (MARPOR/CMP) quantifies policy positions—including internationalism, European integration, foreign policy, and domestic political stances—from party manifestos across democratic European countries (including EU members, North Macedonia, Albania, etc.) with updates covering elections in the 2020s."
    },
    {
      "title": "Parliaments and Governments Database (ParlGov)",
      "url_or_doi": "https://doi.org/10.7910/DVN/2VZ5ZC",
      "justification": "ParlGov provides linked data on political parties, national parliamentary elections, and cabinet compositions across EU and OECD democracies in Europe, with regular updates covering political developments into the 2020s."
    },
    {
      "title": "Human Rights Violations Reporting Dataset (HURIVIRE)",
      "url_or_doi": "https://doi.org/10.5281/zenodo.17286060",
      "justification": "HURIVIRE aggregates country reports from major international organizations (Amnesty International, Human Rights Watch, US State Department, and UN WGEID) covering human rights and international political monitoring across countries including the specified European states from 1999 to 2023."
    }
  ]
}
